@spec vm_extra_cols_spec  src=tests/specs/vm_extra_cols_spec.lua  loc=172  cases=4
@exercises trackerView (h.vm), editCursor (h.ec), dataStore (h.ds), trackerManager (h.tm)
@surface   vm:setGridSize, ec:setPos, vm:hideExtraCol, ds:get, ds:assign, tm:rebuild
@harness   mk{seed.notes}

# Intent
  Pins hideExtraCol's contract: only the topmost empty lane drops, from
  any lane. See docs/trackerView.md § Extra columns & delay sub-column.

# Helpers
  @fn noteColsOn(h, chan)  @ 14-20

# Cases
  @case 'hideExtraCol on topmost empty note lane shrinks extraColumns'  [harness]  @ 25-58
  @case 'hideExtraCol from a lower lane drops the topmost empty lane'  [harness]  @ 62-92
  @case 'hideExtraCol with an occupied top lane is a no-op'  [harness]  @ 96-132
  @case 'hideExtraCol drops the top authored lane past a provisional one'  [harness]  @ 136-169

# Uses (outbound edges)
  @use call vm:setGridSize  @ 36,75,109,149
  @use call ec:setPos  @ 43,77,115,158
  @use call vm:hideExtraCol  @ 44,78,116,159
  @use call ds:get  @ 46,80,118,161
